import { UnauthorizedException } from '@nestjs/common';
import type { UploadsModuleOptions } from '@nestvexa/uploads';
import { resolve } from 'node:path';

/**
 * Generated by `nestvexa add uploads`. Purposes are an explicit allowlist
 * (`<live-component>.<field>` for Live fields). The directory must be private
 * and outside any webroot; set UPLOADS_DIRECTORY in production.
 */
export const uploadsOptions: UploadsModuleOptions = {
  global: true,
  origin: process.env['NESTVEXA_ORIGIN'] ?? 'http://localhost:3000',
  directory: resolve(process.env['UPLOADS_DIRECTORY'] ?? 'storage/uploads'),
  resolveIdentity: (request) => {
    const session: unknown = Reflect.get(request, 'session');
    const id: unknown = Reflect.get(request, 'sessionID');
    const csrf: unknown =
      session && typeof session === 'object' ? Reflect.get(session, 'csrf') : undefined;
    if (typeof id !== 'string' || typeof csrf !== 'string') throw new UnauthorizedException();
    return { binding: `session:${id}`, csrfToken: csrf };
  },
  authorize: (_identity, purpose) => Object.hasOwn(uploadsOptions.purposes, purpose),
  purposes: {
    'attachments.files': { types: ['png', 'jpeg', 'pdf'], maxFileSize: 5 * 1024 * 1024, maxFiles: 5 },
  },
};
